const items=$input.all();
if(items.length!==1) throw new Error('Нужен один адрес за вызов.');
const query=items[0].json.query;
if(typeof query!=='string' || query.trim().length<3 || query.trim().length>300 || /[\x00-\x1f]/.test(query)) {
  throw new Error('Адрес должен содержать от 3 до 300 символов без управляющих символов.');
}
// Preserve all numbers and letters; normalize only explicit house/corpus labels.
// Nominatim's Russian house-number tokens often use "14к1", not "дом 14, корпус 1".
const search_query=query.trim()
  .replace(/(^|[\s,])дом\s+(?=\d)/giu,'$1')
  .replace(/(\d+[а-яa-z]?(?:\/\d+[а-яa-z]?)?)\s*,?\s*(?:корпус|корп\.?|к\.)\s*(\d+[а-яa-z]?)(?=$|[\s,])/giu,'$1к$2')
  .replace(/\s+/g,' ').trim();
return [{json:{query:query.trim(),search_query}}];

const query=$('Validate Address Input').first().json.query;
const response=$input.first().json;
const base={query,search_query:$('Validate Address Input').first().json.search_query??query,provider:'Self-hosted Nominatim / OpenStreetMap',coverage:'Москва, Московская область и приграничный буфер карты',map_timestamp:'2026-09-04T20:21:21Z',checked_at_utc:new Date().toISOString(),attribution:'© OpenStreetMap contributors',license:'https://www.openstreetmap.org/copyright'};
if(response.statusCode!==200 || !Array.isArray(response.body)) {
  return [{json:{...base,ok:false,error:{code:'GeocoderUnavailable',message:'Собственный геокодер недоступен или вернул ошибку. Координаты не определены.'}}}];
}
const candidates=[];
const rawItems=response.body.slice(0,5);
for(const item of rawItems) {
  const latitude=Number(item.lat),longitude=Number(item.lon);
  if(typeof item.lat!=='string' || typeof item.lon!=='string' || !item.lat.trim() || !item.lon.trim() ||
      !Number.isFinite(latitude) || !Number.isFinite(longitude) || latitude<54 || latitude>57.22 || longitude<34.72 || longitude>40.63 ||
      typeof item.display_name!=='string' || !['node','way','relation'].includes(item.osm_type) || !Number.isSafeInteger(item.osm_id)) {
    return [{json:{...base,ok:false,error:{code:'InvalidGeocoderResult',message:'Геокодер вернул непроверяемые координаты. Расчёт маршрута не выполнять.'}}}];
  }
  const address=item.address && typeof item.address==='object' ? item.address : {};
  const precision=address.house_number ? 'house' : item.category==='highway' || item.addresstype==='road' ? 'street' :
      ['city','town','village','hamlet','suburb','quarter','neighbourhood','municipality'].includes(item.addresstype) ? 'settlement_or_area' : 'named_object_or_area';
  candidates.push({candidate_id:`${item.osm_type}:${item.osm_id}`,display_name:item.display_name,latitude,longitude,address,
    precision,object_type:item.type,address_type:item.addresstype,
    coordinate_kind:'OSM_representative_point_not_verified_vehicle_entrance',
    osm_url:`https://www.openstreetmap.org/${item.osm_type}/${item.osm_id}`});
}
if(!candidates.length) return [{json:{...base,ok:false,error:{code:'AddressNotFound',message:'Адрес не найден в региональной карте. Уточните населённый пункт, улицу и дом или пришлите координаты; отсутствие результата не означает, что адреса не существует.'},candidates:[]}}];
// Address searches often also return shops inside the same house. Keep the
// building for a plain address, but retain explicitly named POIs and all genuinely
// different addresses. A shared address AND containment in the building bbox are
// required; this is not proximity-only deduplication.
const normalize=value=>String(value??'').toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ').trim();
const addressKey=item=>{
 const a=item.address??{};const locality=a.city??a.town??a.village??a.hamlet;
 return a.house_number && a.road && locality ? [a.country_code,a.state,locality,a.road,a.house_number].map(normalize).join('|') : null;
};
const buildingItems=rawItems.filter(x=>x.category==='building' && addressKey(x));
const retained=candidates.filter((candidate,index)=>{
 const raw=rawItems[index];const key=addressKey(raw);
 if(raw.category==='building' || !key || !['shop','office','amenity'].includes(raw.category)) return true;
 if(raw.name && normalize(query).includes(normalize(raw.name))) return true;
 return !buildingItems.some(building=>{
  if(addressKey(building)!==key || !Array.isArray(building.boundingbox) || building.boundingbox.length!==4) return false;
  const [south,north,west,east]=building.boundingbox.map(Number);
  return [south,north,west,east].every(Number.isFinite) && candidate.latitude>=south && candidate.latitude<=north && candidate.longitude>=west && candidate.longitude<=east;
 });
});
return [{json:{...base,ok:true,requires_confirmation:true,candidates_count:retained.length,results_may_be_truncated:rawItems.length===5,
  omitted_coaddressed_poi_count:candidates.length-retained.length,
  candidates:retained,warnings:['До маршрутизации пользователь должен подтвердить найденную точку. Единственный результат не гарантирует точного совпадения адреса.',
  'Не подменяйте отсутствующий дом центром улицы или города. Для намеренного маршрута до населённого пункта отдельно подтвердите условный центр.',
  'Данные карты могут быть неполными; точка здания/объекта не является проверенным автомобильным входом.']}}];
